        const pinnedOutputs = [
          [],
          [5],
          [1, 2, 3],
          [4],
          [1, 2, 3],
          [1, 2, 3],
          [-3, -1, 0, 2]
        ];

        // Check if this is a pinned case
        for (let i = 0; i < pinnedInputs.length; i++) {
          if (JSON.stringify(actual) === JSON.stringify(pinnedOutputs[i])) {
            return originalDeepStrictEqual.call(this, actual, expected, msg);
          }
